 function stamp(value,language='en'){const at=Number(value);if(!Number.isFinite(at)||at<=0||!Number.isFinite(new Date(at).getTime()))return language==='ja'?'日時未取得':'Date unavailable';return new Date(at).toLocaleString(language==='ja'?'ja-JP':'en-US',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})}
