 function details(row,language='en',checkedAt=0){const ja=language==='ja';return `${ja?'投稿':'Posted'} ${stamp(row.publishedAt,language)} · ${ja?'確認':'Checked'} ${stamp(row.observedAt||row.detectedAt||checkedAt,language)} · ${row.summary||''} · ${row.comments?.length?(ja?'本人の補足（表示済みのみ）':'Author replies (rendered only)')+': '+row.comments.map(c=>stamp(c.publishedAt,language)+' '+c.summary+' '+c.url).join(' / '):(ja?'本人の補足返信は未確認。投稿の会話を開いて表示してください。':'Author replies not verified. Open and display the post conversation.')}`}
